	      for (second <- extended) {
		second match {
		  case STraitTypeWhere(_,other@STraitType(_,_,_,_),_) =>
		    if ( new_analyzer.definitelyExcludes(st, other) )
		      error(errors, "Types " + st + " and " + other +
